sections.syntax:
-- All columns:
SELECT * FROM table_name;

-- Specific columns:
SELECT column1, column2 FROM table_name;

SELECT column1, column2
FROM table_name
WHERE condition;

examples.code:
SELECT name, age
FROM Students
WHERE age > 21;

SELECT name, age, email
FROM Students
WHERE age >= 18 AND age <= 25;

-- OR example:
SELECT * FROM Products
WHERE category = 'Electronics' OR price < 20;

SELECT product_name, price
FROM Products
WHERE price BETWEEN 10 AND 100;

-- Names starting with 'A':
SELECT * FROM Students WHERE name LIKE 'A%';

-- Names ending with 'son':
SELECT * FROM Students WHERE name LIKE '%son';

-- Names containing 'ali':
SELECT * FROM Students WHERE name LIKE '%ali%';

-- Find employees with no department:
SELECT * FROM Employees WHERE department IS NULL;

-- Find employees that DO have a department:
SELECT * FROM Employees WHERE department IS NOT NULL;

sections.syntax:
SELECT column1, column2
FROM table_name
ORDER BY column1 [ASC|DESC], column2 [ASC|DESC];

examples.code:
SELECT name, age
FROM Students
ORDER BY age ASC;

SELECT product_name, price
FROM Products
ORDER BY price DESC;

SELECT name, department, salary
FROM Employees
ORDER BY department ASC, salary DESC;

sections.syntax:
-- MySQL / PostgreSQL:
SELECT * FROM table_name LIMIT n;
SELECT * FROM table_name LIMIT n OFFSET skip;

-- SQL Server:
SELECT TOP n * FROM table_name;

examples.code:
-- Page 1 (rows 1-10):
SELECT * FROM Products ORDER BY product_id LIMIT 10 OFFSET 0;

-- Page 2 (rows 11-20):
SELECT * FROM Products ORDER BY product_id LIMIT 10 OFFSET 10;

-- Page 3 (rows 21-30):
SELECT * FROM Products ORDER BY product_id LIMIT 10 OFFSET 20;

SELECT DISTINCT city, country
FROM Customers
ORDER BY country, city;

sections.syntax:
-- Column alias:
SELECT column_name AS alias_name FROM table;

-- Table alias:
SELECT t.column FROM table_name AS t;

SELECT column, AGGREGATE_FUNCTION(other_column)
FROM table_name
GROUP BY column;

examples.code:
SELECT name, age
FROM Students
WHERE age > (SELECT AVG(age) FROM Students);

SELECT product_name
FROM Products
WHERE product_id NOT IN (
  SELECT DISTINCT product_id FROM OrderItems
);
